#!/usr/bin/env bash
#
# A wizard walks a human through Figma setup for WSL development.
# Generated by the wizard skill.
#

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-frontend/.env.design.local}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do

_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  你只需在浏览器中完成操作；脚本会提供精准指引并自动捕获 Token 与配置。%s\n' "$DIM" "$RESET"
  printf '%s  随时可按 Ctrl-C 退出，已保存的配置会自动记住，支持重跑。%s\n\n' "$DIM" "$RESET"
  pause "准备好开始了吗？按 Enter 键继续..."
}

stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ 步骤 %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

say()  { printf '  %s\n' "$1"; }
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

open_url() {
  local url="$1"
  printf '  %s↗ 正在打开%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "无法自动打开浏览器，请手动访问: $url"; fi
  } >/dev/null 2>&1 || warn "无法自动打开浏览器，请手动访问: $url"
}

pause() {
  printf '  %s%s%s ' "$DIM" "${1:-完成上述操作后按 Enter 继续...}" "$RESET"
  read -r _ || true
}

confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter 保留当前值]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter 保留当前值]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

write_env() {
  local key="$1" value="$2" tmp dir
  dir=$(dirname "$ENV_FILE")
  mkdir -p "$dir"
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ 已写入%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

finish() {
  _clear
  printf '\n%s%s  ✓ 配置全部完成！%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} )) && note "已保存环境变量至 $ENV_FILE: ${WRITTEN_ENV[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "后续需手动留意的项:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
  say "你现在可以在 WSL 中让 Codex / Agent 读取 Figma 设计稿了！"
  say "示例用法: 在 WSL 终端对 Codex 提示："
  note "  codex \"请帮我分析这个 Figma 节点并用 Vue 3 还原: https://www.figma.com/design/<file-key>?node-id=<id>\""
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: Figma & WSL 开发环境集成向导
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=4

banner "Figma + WSL 前端开发环境向导"

# ── Stage 1: 教育优惠申请 ──────────────────────────────────────────────────
stage "申请 Figma 教育优惠（上海大学 edu 邮箱认证）"
say "通过教育认证可免费获得 Professional 席位，MCP 额度从 20次/月 提升到 200次/天。"
say ""
step "1. 确保当前 Figma 账号邮箱为你的上大邮箱（xxx@shu.edu.cn）。"
note "   （若非 edu 邮箱，请先在 Figma 设置中将主邮箱修改为学校邮箱）"
step "2. 即将为你打开教育认证申请页面。"
step "3. 填写申请表："
note "   - 机构类型选择: Higher Ed (高等教育)"
note "   - 学校名称选择/填写: Shanghai University"
note "   - 身份选择: Student"
open_url "https://www.figma.com/education/apply"
say ""
pause "在浏览器中完成 SheerID 验证后，按 Enter 继续..."

# ── Stage 2: 生成 Figma PAT 与捕获设计稿 Key ───────────────────────────────
stage "获取 Figma 访问令牌 (PAT) 与目标设计稿 Key"
say "PAT 用于本地脚本导出高清图片/SVG 资产以及提取节点树。"
say ""
step "1. 即将打开 Figma Settings 页面。"
step "2. 下滑至 'Personal access tokens' 分区，点击 'Generate new token'。"
step "3. 勾选只读权限: 'file_content:read'，然后点击生成并复制该 Token。"
open_url "https://www.figma.com/settings"
say ""
ask_secret FIGMA_TOKEN "请粘贴复制的 Figma PAT (输入不回显):"
write_env "FIGMA_TOKEN" "$FIGMA_TOKEN"

say ""
step "4. 打开你想接入的项目设计稿（例如你的 case-lib 设计文件），复制浏览器地址栏 URL。"
note "   地址栏格式通常为: https://www.figma.com/design/<FILE_KEY>/<TITLE>?node-id=..."
ask FIGMA_URL "请粘贴设计稿 URL 或直接输入 FILE_KEY:"

# 自动从 URL 中提取 File Key
FIGMA_FILE_KEY="$FIGMA_URL"
if [[ "$FIGMA_URL" =~ figma\.com/(design|file)/([^/?]+) ]]; then
  FIGMA_FILE_KEY="${BASH_REMATCH[2]}"
fi
write_env "FIGMA_FILE_KEY" "$FIGMA_FILE_KEY"
say "  已解析并记录 FILE_KEY: $FIGMA_FILE_KEY"
pause

# ── Stage 3: 配置 WSL Codex / Claude 的 Remote MCP ─────────────────────────
stage "在 WSL 中注册 Figma 官方 Remote MCP"
say "Figma 官方 Remote MCP 运行在云端，通过 OAuth 直接打通 WSL，无需 Windows 端口映射。"
say ""

if command -v codex >/dev/null 2>&1; then
  step "检测到 WSL 中已安装 Codex CLI，准备添加 figma MCP..."
  if confirm "是否立即执行 'codex mcp add figma --url https://mcp.figma.com/mcp'？"; then
    say "正在调用 codex 注册 MCP 并触发浏览器授权..."
    codex mcp add figma --url https://mcp.figma.com/mcp || warn "Codex MCP 注册返回非零，可能需要手动授权"
  fi
else
  note "未在 WSL 路径中找到 codex 命令，跳过自动注册。"
  SKIPPED+=("Codex MCP: 后续可在安装 codex 后手动运行 'codex mcp add figma --url https://mcp.figma.com/mcp'")
fi

say ""
step "如果你使用的是 VS Code / Cursor 或 Claude Code，可在对应 MCP 配置加入："
note "  URL: https://mcp.figma.com/mcp"
note "  （无需配置本地端口，打开链接完成 OAuth 即可）"
pause

# ── Stage 4: 快速连通性验证 ────────────────────────────────────────────────
stage "验证 Figma REST API 与 Token 连通性"
say "脚本将尝试用刚保存的 Token 与 FILE_KEY 读取一次设计稿元数据..."

HTTP_CODE=$(curl -s -o /tmp/figma_test_res.json -w "%{http_code}" \
  -H "X-Figma-Token: $FIGMA_TOKEN" \
  "https://api.figma.com/v1/files/$FIGMA_FILE_KEY?depth=1" || echo "000")

if [[ "$HTTP_CODE" == "200" ]]; then
  FILE_NAME=$(grep -o '"name":"[^"]*"' /tmp/figma_test_res.json | head -n1 | cut -d'"' -f4 || echo "未知")
  printf '  %s✓ API 连通成功！读取到设计稿名称: %s%s\n' "$GREEN" "$FILE_NAME" "$RESET"
else
  warn "API 校验未返回 200 (状态码: $HTTP_CODE)。可能是 Token 未生效或 FILE_KEY 不正确。"
  note "响应详情已暂存至 /tmp/figma_test_res.json"
fi
pause

finish
